// A local stand-in for @supabase/supabase-js, backed by a JSON file, present
// so the generated entitlement module can be EXECUTED in tests.
//
// It implements the subset of the query builder Akeso generates against, with
// the same semantics that matter:
//   - .eq() chains AND together, so a compare-and-set update whose expected
//     value no longer matches updates zero rows (the race must lose)
//   - .maybeSingle() returns { data: null } for a miss, never an error
//   - errors come back as VALUES in { error }, never thrown — the exact shape
//     that made a previous version of this project report a missing column as
//     "not entitled"
import { readFile, writeFile } from "node:fs/promises";

const store = () => process.env.AKESO_FIXTURE_DB;

async function load() {
  try { return JSON.parse(await readFile(store(), "utf8")); }
  catch { return { tables: {} }; }
}

class Query {
  constructor(table, op, payload) {
    this.table = table;
    this.op = op;
    this.payload = payload;
    this.filters = [];
  }
  select() { return this; }
  eq(column, value) { this.filters.push([column, value]); return this; }

  matches(row) {
    return this.filters.every(([column, value]) => String(row[column]) === String(value));
  }

  async run() {
    const db = await load();
    const rows = db.tables[this.table];

    // A query against a table that does not exist is an ERROR, not an empty
    // result. Reporting it as "no rows" is how a missing column silently
    // becomes "this customer is not entitled".
    if (!rows) return { data: null, error: { message: `relation "${this.table}" does not exist` } };

    if (this.op === "select") return { data: rows.filter((row) => this.matches(row)), error: null };

    if (this.op === "update") {
      let changed = 0;
      for (const row of rows) {
        if (!this.matches(row)) continue;
        Object.assign(row, this.payload);
        changed += 1;
      }
      await writeFile(store(), JSON.stringify(db, null, 2));
      return { data: null, error: null, count: changed };
    }

    if (this.op === "insert") {
      rows.push({ ...this.payload });
      await writeFile(store(), JSON.stringify(db, null, 2));
      return { data: null, error: null };
    }

    if (this.op === "upsert") {
      const keys = Object.keys(this.payload);
      const key = keys.includes("account_id") ? "account_id" : keys[0];
      const existing = rows.find((row) => String(row[key]) === String(this.payload[key]));
      if (existing) Object.assign(existing, this.payload);
      else rows.push({ ...this.payload });
      await writeFile(store(), JSON.stringify(db, null, 2));
      return { data: null, error: null };
    }

    return { data: null, error: { message: `unsupported operation ${this.op}` } };
  }

  async maybeSingle() {
    const { data, error } = await this.run();
    if (error) return { data: null, error };
    return { data: data?.[0] ?? null, error: null };
  }

  // Awaiting the builder directly runs it, like the real client.
  then(resolve, reject) { return this.run().then(resolve, reject); }
}

export function createClient(url, key) {
  if (!url || !key) throw new Error("supabase client needs a url and a key");
  return {
    from(table) {
      return {
        select: () => new Query(table, "select"),
        update: (payload) => new Query(table, "update", payload),
        insert: (payload) => new Query(table, "insert", payload),
        upsert: (payload) => new Query(table, "upsert", payload),
      };
    },
  };
}
